<script setup lang="ts">
import {Head,Link,router,useForm} from '@inertiajs/vue3';
import Shell from '../Layouts/Shell.vue';
defineProps<{leads:{data:{id:number;name:string;club:string;contact:string;pc_count:number;plan:string;message:string|null;status:string;created_at:string}[];prev_page_url:string|null;next_page_url:string|null;total:number};status:string;newCount:number}>();
const form=useForm({status:''});
function update(id:number,event:Event){form.status=(event.target as HTMLSelectElement).value;form.post('/connection-requests/'+id,{preserveScroll:true});}
const labels:Record<string,string>={new:'Новый',contacted:'Связались',closed:'Завершён'};
</script>
<template><Head title="Запросы на подключение"/><Shell><div class="heading"><div><h1>Запросы на подключение</h1><p>Новых: {{newCount}} · Всего в выборке: {{leads.total}}</p></div><label>Статус<select :value="status" @change="router.get('/connection-requests',{status:($event.target as HTMLSelectElement).value})"><option value="">Все</option><option v-for="(label,key) in labels" :value="key" :key="key">{{label}}</option></select></label></div><p v-for="error in form.errors" :key="error" class="error">{{error}}</p><p v-if="!leads.data.length" class="panel">Запросов пока нет.</p><article v-for="lead in leads.data" :key="lead.id" class="panel lead"><div class="toolbar"><h2>{{lead.club}}</h2><label>Обработка #{{lead.id}}<select :value="lead.status" :disabled="form.processing" @change="update(lead.id,$event)"><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label></div><dl><div><dt>Контакт</dt><dd>{{lead.name}} · {{lead.contact}}</dd></div><div><dt>Компьютеров</dt><dd>{{lead.pc_count}}</dd></div><div><dt>Тариф</dt><dd>{{({standard:'Обслуживание',priority:'Приоритет',custom:'Индивидуально'} as Record<string,string>)[lead.plan]}}</dd></div><div><dt>Получен (Ташкент)</dt><dd>{{new Date(lead.created_at).toLocaleString('ru-RU',{timeZone:'Asia/Tashkent'})}}</dd></div></dl><p class="prewrap">{{lead.message}}</p></article><div class="pagination"><Link v-if="leads.prev_page_url" :href="leads.prev_page_url">Назад</Link><Link v-if="leads.next_page_url" :href="leads.next_page_url">Далее</Link></div></Shell></template>
<style scoped>.lead dl{display:grid;grid-template-columns:2fr 1fr 1fr 1fr;gap:20px;margin:20px 0}.lead dt{font-size:12px;color:var(--muted)}.lead dd{margin:6px 0;overflow-wrap:anywhere}@media(max-width:800px){.lead dl{grid-template-columns:1fr 1fr}}</style>
